var n=`0926-ants-climbing-a-tree`;var t=`world-0926`;var a=`CN`;var s=`east-asia`;var r=4;var o=40;var g={en:`Ants Climbing a Tree`,ua:`Мурахи на дереві`};var d={en:`Ants Climbing a Tree is a China dish made with glass noodles, ground pork, doubanjiang, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Мурахи на дереві, страва кухні країни Китай. Основні складники: скляна локшина, свинячий фарш, доубаньцзян, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Soak the listed rice, grains or noodles in clean water for about 15 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 15 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`soaking-dried-produce`],m:15,i:[[`glass-noodles`,300,`g`],[`water`,680,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`ground-pork`,340,`g`],[`peanut-oil`,40,`ml`],[`doubanjiang`,35,`g`],[`ground-ginger`,20,`g`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 12 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 12 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:12,i:[[`chicken-stock`,480,`ml`],[`light-soy-sauce`,40,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,55,`g`],[`toasted-sesame-oil`,15,`ml`]]}];var u={slug:n,id:t,country:`CN`,region:s,servings:4,minutes:40,title:g,text:d,steps:l};export{a as country,u as default,t as id,o as minutes,s as region,r as servings,n as slug,l as steps,d as text,g as title};